import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        Solver sol = new Solver();
        sol.process(1, in, out);
        out.close();
    }

    static class Solver {
        static final int IMPOSSIBLE_VALUE = 11111;
        int rows;
        int columns;
        Map<BitState, Integer>[] memoTable;

        boolean checkBit(int state, int position) {
            if (position < 0) return false;
            return ((state >> position) & 1) == 1;
        }

        int enableBit(int state, int position) {
            if (((state >> position) & 1) == 0) {
                state |= (1 << position);
            }
            return state;
        }

        int bitFrequency(int state) {
            int cnt = 0;
            while (state > 0) {
                cnt += (state & 1);
                state >>>= 1;
            }
            return cnt;
        }

        void preflightChecks() {
            if (!checkBit(5, 0)) throw new AssertionError("Bit 0 not set in 5");
            if (checkBit(5, 1)) throw new AssertionError("Bit 1 set in 5");
            if (checkBit(5, -1)) throw new AssertionError("Negative index issue");
            if (!checkBit(5, 2)) throw new AssertionError("Bit 2 not set");
            if (!checkBit(5, 3)) throw new AssertionError("Bit 3 not set");
            if (enableBit(0, 2) != 4) throw new AssertionError("Add bit 2 to 0");
            if (enableBit(4, 0) != 5) throw new AssertionError("Add bit 0 to 4");
            if (enableBit(5, 0) != 5) throw new AssertionError("Redundant add");
            if (bitFrequency(5) != 2) throw new AssertionError("Popcount of 5");
        }

        int recursiveDP(int currentRow, int required, int previousState) {
            if (currentRow == rows) {
                return (required == 0) ? 0 : IMPOSSIBLE_VALUE;
            }
            BitState key = new BitState(required, previousState);
            if (memoTable[currentRow].containsKey(key)) {
                return memoTable[currentRow].get(key);
            }
            int minimum = IMPOSSIBLE_VALUE;
            int numConfigs = 1 << columns;
            for (int config = 0; config < numConfigs; config++) {
                int currentBits = 0;
                for (int col = 0; col < columns; col++) {
                    if (((config >> col) & 1) == 1) {
                        currentBits |= (1 << col);
                    }
                }
                boolean satisfied = true;
                for (int up = 0; up < columns; up++) {
                    if (checkBit(required, up) && !checkBit(currentBits, up)) {
                        satisfied = false;
                        break;
                    }
                }
                if (satisfied) {
                    int nextRequired = 0;
                    for (int col = 0; col < columns; col++) {
                        if (!checkBit(currentBits, col - 1) && !checkBit(currentBits, col) &&
                            !checkBit(currentBits, col + 1) && !checkBit(previousState, col)) {
                            nextRequired |= (1 << col);
                        }
                    }
                    int candidate = bitFrequency(currentBits) + recursiveDP(currentRow + 1, nextRequired, currentBits);
                    if (candidate < minimum) minimum = candidate;
                }
            }
            memoTable[currentRow].put(key, minimum);
            return minimum;
        }

        public void process(int testId, InputReader reader, OutputWriter writer) {
            preflightChecks();
            int dimension1 = reader.readInt();
            int dimension2 = reader.readInt();
            columns = Math.min(dimension1, dimension2);
            rows = Math.max(dimension1, dimension2);
            memoTable = new HashMap[rows];
            for (int i = 0; i < rows; i++) memoTable[i] = new HashMap<>();
            int result = recursiveDP(0, 0, 0);
            writer.printLine(columns * rows - result);
        }
    }

    static class BitState {
        final int firstValue;
        final int secondValue;

        BitState(int a, int b) {
            firstValue = a;
            secondValue = b;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            BitState that = (BitState) o;
            return firstValue == that.firstValue && secondValue == that.secondValue;
        }

        public int hashCode() {
            int hash = 17;
            hash = 31 * hash + firstValue;
            hash = 31 * hash + secondValue;
            return hash;
        }

        public String toString() {
            return "(" + firstValue + "," + secondValue + ")";
        }

        public int compareTo(BitState other) {
            int cmp = Integer.compare(firstValue, other.firstValue);
            if (cmp != 0) return cmp;
            return Integer.compare(secondValue, other.secondValue);
        }
    }

    static class InputReader {
        private final InputStream source;
        private final byte[] buffer = new byte[1024];
        private int bufferIndex = 0;
        private int bufferLimit = 0;

        public InputReader(InputStream input) {
            source = input;
        }

        private int getNextByte() {
            if (bufferIndex == bufferLimit) {
                bufferIndex = 0;
                try {
                    bufferLimit = source.read(buffer);
                } catch (IOException ex) {
                    throw new InputMismatchException();
                }
                if (bufferLimit <= 0) return -1;
            }
            return buffer[bufferIndex++];
        }

        public int readInt() {
            int ch = getNextByte();
            while (isWhitespace(ch)) ch = getNextByte();
            int sign = 1;
            if (ch == '-') {
                sign = -1;
                ch = getNextByte();
            }
            int result = 0;
            while (!isWhitespace(ch)) {
                if (ch < '0' || ch > '9') throw new InputMismatchException();
                result = result * 10 + (ch - '0');
                ch = getNextByte();
            }
            return result * sign;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter output;

        public OutputWriter(OutputStream out) {
            output = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public void close() {
            output.close();
        }

        public void printLine(int value) {
            output.println(value);
        }
    }
}
